export class PerformanceMonitor {
  async measureAsync<T>(fn: () => Promise<T>): Promise<{ result: T; duration: number; success: boolean }> {
    const startTime = Date.now();

    try {
      const result = await fn();
      const duration = Date.now() - startTime;

      return {
        result,
        duration,
        success: true
      };
    } catch (error) {
      const duration = Date.now() - startTime;

      return {
        result: null as T,
        duration,
        success: false
      };
    }
  }
}
