  relationships: CausalRelationship[];
  outcomes: Outcome[];
  confidence: ConfidenceLevel;
}

function mapCausalRelationships(research: ResearchData[]): CausalMap {
  // Extract factors and outcomes
  const factors = extractFactors(research);
